import mapPhysicsData from "../assets/MAP/Givre/givre_01.physics.json";

/**
 * Typed view of the GIVRE 01 game JSON (src/assets/MAP/Givre/givre_01.physics.json,
 * generated by scripts/generate-givre-colliders.mjs from the Blender export).
 *
 * Only the fields the client reads are typed here. The v3 sections (halos,
 * fx, snow, footprints, animations) are optional: an older export without
 * them still loads (the matching effects are simply skipped).
 * Full reference: src/assets/MAP/Givre/reference/givrePhysics.types.ts.
 */
export type Vec2 = [number, number];
export type Vec3 = [number, number, number];

export interface GivreColliderEntry {
  id: string;
  type: "cuboid" | "convexHull";
  position?: number[];
  halfExtents?: number[];
  rotation?: number[];
  vertices?: number[][];
  purpose?: string;
  /** Blender object the collider was built from (v3). */
  source?: string;
}

/** Named XZ rectangle (callouts / stats) straight from the export. */
export interface GivreZone {
  id: string;
  name: string;
  kind: string;
  floorY: number;
  min: number[];
  max: number[];
}

export interface GivreHaloType {
  radius: number | null;
  radiusFactorOfSize: number | null;
  colorHex: string;
  intensity: number;
}

export interface GivreHaloPoint {
  type: string;
  /** Halo radius in metres (already computed by the export). */
  radius: number;
}

export interface GivreHalosData {
  types: Record<string, GivreHaloType>;
  /** Fixed bulbs / lanterns, world coordinates. */
  static: (GivreHaloPoint & { position: Vec3 })[];
  /** Swinging garland bulbs: LOCAL coordinates of the animated node `node`. */
  nodes: { node: string; points: (GivreHaloPoint & { local: Vec3 })[] }[];
}

/** Effect anchor (boiler flicker, sound sources). */
export interface GivreFxData {
  id: string;
  fx: string;
  position: Vec3;
  son?: string;
  boucle?: number;
  instants_s?: number[];
  periode_s?: number;
  duree_s?: number;
  portee_m?: number;
  couleur?: Vec3;
  note?: string;
}

export interface GivreSnowData {
  /** Flake box centred on the camera in XZ: [x, y, z] in m. */
  boxSize: Vec3;
  /** Bottom of the box (world Y); top = yMin + boxSize[1]. */
  yMin: number;
  /** Flakes per m³ at the 'normale' level. */
  density: number;
  flakeSize: number;
  fallSpeed: number;
  wind: Vec3;
  swayAmplitude: number;
  swayHz: number;
  minDistance: number;
  /** Density multipliers per level (legere / normale / dense). */
  levels: Record<string, number>;
}

export interface GivreFootprintsData {
  /** [width, length] of one print in m. */
  size: Vec2;
  lateralOffset: number;
  minStep: number;
  heightAboveSurface: number;
  fullSeconds: number;
  goneSeconds: number;
  poolSize: number;
  surfaceMaterials: string[];
  maxSlopeDeg: number;
}

export interface GivreAnimationsData {
  loopSeconds: number;
  fps: number;
  animatedNodes: number;
  nodes: string[];
}

export interface GivreMaterialInfo {
  baseColorHex: string;
  roughness?: number;
  emissiveHex?: string;
  emissiveStrength?: number;
}

export interface GivreMapData {
  contentVersion?: number;
  colliders: GivreColliderEntry[];
  playerClips: GivreColliderEntry[];
  zones: GivreZone[];
  expansion: { envelopeMin: Vec2; envelopeMax: Vec2 };
  materials: Record<string, GivreMaterialInfo>;
  halos?: GivreHalosData;
  fx?: GivreFxData[];
  snow?: GivreSnowData;
  footprints?: GivreFootprintsData;
  animations?: GivreAnimationsData;
}

export const givreData = mapPhysicsData as unknown as GivreMapData;
